import math

class Solution:
    def bestCoordinate(self, towers: List[List[int]], radius: int) -> List[int]:
        r2 = radius * radius
        bq, bx, by = -1, 0, 0
        for x in range(101):
            for y in range(101):
                q = 0
                for tx, ty, tq in towers:
                    d2 = (tx - x) ** 2 + (ty - y) ** 2
                    if d2 <= r2:
                        q += int(tq / (1 + math.sqrt(d2)))
                if q > bq:
                    bq, bx, by = q, x, y
        return [bx, by]

